files.main.tf:
terraform { required_version = ">= 1.4" }
variable "coder_start_count" { type = number }
variable "message" { type = string }
variable "coder_environment" {
  type = map(string)
  sensitive = true
  default = {}
}
resource "terraform_data" "workspace" {
  count = var.coder_start_count
  input = { message = var.message, secret = lookup(var.coder_environment, "WORKSPACE_TOKEN", "") }
}
